/**
 * The read-only tool page (`docs/user-guide/AVAILABLE_TOOLS_READONLY.md`,
 * generated by `npm run docs:tools`) lists exactly what the read-only
 * binaries serve: the tools of `fullReadOnlyToolSet`, the set
 * `mcp-abap-adt-ro`, `-http-ro` and `-sse-ro` use — not the readonly folders,
 * which also hold the background-run tools — with the parameters they take
 * there. No run tool is there: a read-only set changes nothing in the system.
 * A page generated from the group, or left stale after the set changed, goes
 * red here.
 */
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fullReadOnlyToolSet } from '../../lib/toolSet';

const PAGE = path.join(
  __dirname,
  '..',
  '..',
  '..',
  'docs',
  'user-guide',
  'AVAILABLE_TOOLS_READONLY.md',
);

const page = fs.readFileSync(PAGE, 'utf8');
const lines = page.split('\n');

/** Each `#### <Tool> (Read-Only / <Object>)` heading's tool, with its parameter lines. */
function documented(): Map<string, string[]> {
  const tools = new Map<string, string[]>();
  let current: string[] | undefined;
  for (const line of lines) {
    if (line.startsWith('#### ')) {
      const name = line.slice('#### '.length).split(' ')[0];
      current = [];
      tools.set(name, current);
    } else if (current !== undefined && line.startsWith('- `')) {
      current.push(line);
    }
  }
  return tools;
}

const served = fullReadOnlyToolSet
  .groups({ connection: undefined as never, logger: undefined }, 'stdio')
  .flatMap((group) => group.getHandlers());

describe('the read-only tool page lists exactly what mcp-abap-adt-ro serves', () => {
  it('the same tools, no more and no fewer', () => {
    const names = [...documented().keys()].sort();
    expect(names).toEqual(
      served.map((entry) => entry.toolDefinition.name).sort(),
    );
    expect(page).toContain(`- Total tools: ${served.length}\n`);
  });

  it('no background-run tool and no resume', () => {
    const names = [...documented().keys()];
    for (const name of [
      'GetBackgroundRun',
      'ListBackgroundRuns',
      'DiscardBackgroundRun',
      'ResumeLeftoverSession',
    ]) {
      expect({ name, listed: names.includes(name) }).toEqual({
        name,
        listed: false,
      });
    }
  });

  it('no run tool, no trace schedule, no logoff, and no tool takes background', () => {
    const tools = documented();
    for (const name of [
      'RuntimeRunClass',
      'RuntimeRunProgram',
      'RuntimeCreateProfilerTraceParameters',
      'LogoffLeftoverSession',
    ]) {
      expect({ name, listed: tools.has(name) }).toEqual({
        name,
        listed: false,
      });
    }
    const withBackground = [...tools.entries()]
      .filter(([, params]) =>
        params.some((p) => p.startsWith('- `background`')),
      )
      .map(([name]) => name);
    expect(withBackground).toEqual([]);
    expect(page).not.toContain('GetBackgroundRun');
  });
});
